css:
/* The institute green appears on the title and the signature labels, exactly
   where the paper document uses it. Written out literally in both places rather
   than as a custom property: this site renders PDFs with wkhtmltopdf, whose
   WebKit predates CSS variables, so a var() would look correct in the browser
   preview and come out black in the PDF anyone actually receives. Adjust both if
   it reads off against the letterhead. */
.proof-of-registration {
	font-size: 11pt;
	line-height: 1.45;
	color: #000;
}

.proof-letterhead {
	margin-bottom: 18px;
}
/* The letterhead is a single image and carries its own whitespace; without this
   it renders at whatever intrinsic size it has and pushes the document down the
   page. */
.proof-letterhead img {
	max-width: 100%;
	height: auto;
}

.proof-title {
	text-align: center;
	font-size: 16pt;
	font-weight: bold;
	color: #1a7a3c;
	margin: 0 0 26px;
}

.proof-date {
	text-align: right;
	margin: 0 0 26px;
}

/* Fixed label and colon columns, so the colons sit in a line rather than
   wherever each label happens to end. */
.proof-identity {
	border: none;
	border-collapse: collapse;
	margin: 0 0 34px;
	font-weight: bold;
}
.proof-identity td {
	border: none;
	padding: 0 0 3px;
	vertical-align: top;
	white-space: nowrap;
}
.proof-identity td.label {
	width: 105px;
}
.proof-identity td.colon {
	width: 14px;
}

.proof-lead {
	margin: 0 0 22px;
}

.proof-qualification {
	margin: 0 0 24px;
}

.proof-modules {
	width: 100%;
	border-collapse: collapse;
	margin: 0 0 28px;
}
.proof-modules th,
.proof-modules td {
	border: none;
	text-align: left;
	padding: 1px 0;
	font-weight: normal;
}
.proof-modules th {
	padding-bottom: 10px;
	font-weight: bold;
}
/* Fixed rather than proportional, so the names line up in a column the way the
   typed original does. */
.proof-modules .module-code {
	width: 190px;
}

.proof-period {
	margin: 0 0 18px;
}

.proof-acknowledgement {
	margin: 0 0 10px;
}

/* The mark sits directly on the rule, so the signature reads as signed rather
   than as an image placed near a line. */
.proof-signature {
	margin-top: 42px;
	page-break-inside: avoid;
}
.proof-signature .signature-image {
	display: block;
	height: 50px;
	width: auto;
	max-width: 250px;
	margin-bottom: -8px;
}
.proof-signature .signature-space {
	height: 42px;
}
.proof-signature .signature-rule {
	border-top: 1px solid #000;
	width: 230px;
}
.proof-signature .signature-label {
	font-weight: bold;
	color: #1a7a3c;
	padding-top: 3px;
}
